"""Entire CLI adapter for DevMemory.

Wraps the Entire CLI (Go binary) to inspect checkpoints, transcripts,
developer intents, agents, and graph impact.
"""

import json
import os
import shutil
import subprocess
from typing import Optional, List, Dict, Any


class EntireAdapter:
    """Wraps the Entire CLI to extract checkpoint data and session context."""

    def __init__(self, repo_path: str):
        self.repo_path = os.path.abspath(repo_path)
        self._entire_bin = shutil.which("entire") or "entire"

    def is_available(self) -> bool:
        """Check if Entire CLI is installed and responsive."""
        try:
            result = subprocess.run(
                [self._entire_bin, "status", "--json"],
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=10,
            )
            return result.returncode == 0
        except (FileNotFoundError, subprocess.SubprocessError, PermissionError):
            return False

    def get_version(self) -> Optional[str]:
        """Get Entire CLI version string if installed."""
        try:
            result = subprocess.run(
                [self._entire_bin, "version"],
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=5,
            )
            if result.returncode == 0:
                return result.stdout.strip()
        except Exception:
            pass
        return None

    def get_checkpoint_id_from_commit(self, commit_message: str) -> Optional[str]:
        """Extract Entire-Checkpoint trailer from a git commit message."""
        if not commit_message:
            return None
        for line in commit_message.strip().split("\n"):
            line = line.strip()
            if line.lower().startswith("entire-checkpoint:"):
                parts = line.split(":", 1)
                if len(parts) > 1:
                    val = parts[1].strip()
                    if val:
                        return val
        return None

    def list_checkpoints(self) -> List[Dict[str, Any]]:
        """List all checkpoints via `entire checkpoint list --json`."""
        try:
            result = subprocess.run(
                [self._entire_bin, "checkpoint", "list", "--json"],
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=30,
            )
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except Exception:
            pass
        return []

    def explain_checkpoint(self, checkpoint_id: str) -> Optional[Dict[str, Any]]:
        """Get full checkpoint context via `entire checkpoint explain <id> --json`."""
        if not checkpoint_id:
            return None
        try:
            result = subprocess.run(
                [self._entire_bin, "checkpoint", "explain", checkpoint_id, "--json"],
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=30,
            )
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except Exception:
            pass
        return None

    def extract_intent(self, checkpoint_data: Optional[Dict[str, Any]]) -> Optional[str]:
        """Extract the developer's intent from checkpoint transcript or summary.

        The intent is typically the first user prompt in the session transcript.
        """
        if not checkpoint_data:
            return None

        # Check transcript user messages
        transcript = checkpoint_data.get("transcript") or []
        if isinstance(transcript, list):
            for turn in transcript:
                if isinstance(turn, dict) and turn.get("role") in ("user", "human"):
                    content = turn.get("content") or turn.get("text") or ""
                    if content:
                        return str(content).strip()[:500]

        # Check prompts field
        prompts = checkpoint_data.get("prompts") or []
        if isinstance(prompts, list) and prompts:
            first = prompts[0]
            if isinstance(first, dict):
                return (first.get("content") or first.get("prompt") or "")[:500]
            elif isinstance(first, str):
                return first[:500]

        # Fallback to summary or title
        for key in ("summary", "intent", "title", "description"):
            val = checkpoint_data.get(key)
            if val and isinstance(val, str):
                return val.strip()[:500]

        return None

    def extract_agent(self, checkpoint_data: Optional[Dict[str, Any]]) -> Optional[str]:
        """Extract which AI agent created this checkpoint."""
        if not checkpoint_data:
            return None
        for key in ("agent", "agent_name", "model", "assistant", "author"):
            val = checkpoint_data.get(key)
            if val and isinstance(val, str):
                return val.strip()
        metadata = checkpoint_data.get("metadata")
        if isinstance(metadata, dict):
            for key in ("agent", "agent_name", "model"):
                val = metadata.get(key)
                if val and isinstance(val, str):
                    return val.strip()
        return None

    def search_checkpoints(self, query: str) -> List[Dict[str, Any]]:
        """Search checkpoints via `entire checkpoint search <query> --json`."""
        if not query:
            return []
        try:
            result = subprocess.run(
                [self._entire_bin, "checkpoint", "search", query, "--json"],
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=30,
            )
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except Exception:
            pass
        return []

    def get_impact_analysis(self, changed_files: List[str]) -> Optional[Dict[str, Any]]:
        """Use Entire Graph plugin to find affected modules if available."""
        if not changed_files:
            return None
        try:
            cmd = [self._entire_bin, "graph", "impact", "--files"] + list(changed_files) + ["--json"]
            result = subprocess.run(
                cmd,
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=20,
            )
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except Exception:
            pass
        return None

"""GitAdapter for DevMemory using GitPython.

Handles commit inspection, diff calculation, branch detection, and safe restores.
"""

import os
from typing import Optional, List, Dict, Any
import git


class GitAdapter:
    """Encapsulates git repository operations via GitPython."""

    def __init__(self, repo_path: str):
        self.repo_path = os.path.abspath(repo_path)
        self._repo: Optional[git.Repo] = None

    @property
    def repo(self) -> git.Repo:
        if self._repo is None:
            self._repo = git.Repo(self.repo_path)
        return self._repo

    def is_git_repo(self) -> bool:
        """Check if target path is an initialized git repository."""
        try:
            _ = self.repo.head
            return True
        except (git.InvalidGitRepositoryError, git.NoSuchPathError, TypeError):
            return False
        except Exception:
            return os.path.exists(os.path.join(self.repo_path, ".git"))

    def get_head_commit(self) -> Optional[Dict[str, Any]]:
        """Get HEAD commit details."""
        try:
            commit = self.repo.head.commit
            parent_sha = commit.parents[0].hexsha if commit.parents else None
            return {
                "sha": commit.hexsha,
                "short_sha": commit.hexsha[:7],
                "message": commit.message.strip(),
                "author": str(commit.author),
                "timestamp": commit.committed_datetime.isoformat(),
                "parent": parent_sha,
            }
        except Exception:
            return None

    def get_diff_stats(self, commit_a: Optional[str], commit_b: Optional[str]) -> Dict[str, Any]:
        """Compute diff statistics (files, additions, deletions, diff text) between two commits."""
        default_res = {
            "files": [],
            "additions": 0,
            "deletions": 0,
            "diff": "",
        }
        if not commit_b:
            return default_res

        try:
            if not commit_a:
                try:
                    diff_text = self.repo.git.show(commit_b, format="", stat=False)
                    numstat = self.repo.git.show(commit_b, format="", numstat=True)
                except Exception:
                    diff_text = ""
                    numstat = ""
            else:
                diff_text = self.repo.git.diff(commit_a, commit_b)
                numstat = self.repo.git.diff(commit_a, commit_b, numstat=True)

            files: List[str] = []
            additions = 0
            deletions = 0

            for line in numstat.strip().split("\n"):
                if not line.strip():
                    continue
                parts = line.split("\t")
                if len(parts) == 3:
                    add = int(parts[0]) if parts[0] != "-" else 0
                    rem = int(parts[1]) if parts[1] != "-" else 0
                    additions += add
                    deletions += rem
                    files.append(parts[2].strip())

            return {
                "files": files,
                "additions": additions,
                "deletions": deletions,
                "diff": diff_text,
            }
        except Exception as e:
            return {
                "files": [],
                "additions": 0,
                "deletions": 0,
                "diff": f"Diff unavailable: {e}",
            }

    def get_diff_text(self, commit_a: str, commit_b: str) -> str:
        """Get raw diff text between two commits."""
        try:
            return self.repo.git.diff(commit_a, commit_b)
        except Exception as e:
            return f"Diff error: {e}"

    def get_branch(self) -> str:
        """Return the active branch name or 'detached'."""
        try:
            return self.repo.active_branch.name
        except (TypeError, ValueError, AttributeError):
            return "detached"
        except Exception:
            return "unknown"

    def restore_commit(self, commit_sha: str) -> str:
        """Safely restore/checkout to a commit using a dedicated recovery branch."""
        branch_name = f"devmemory-restore-{commit_sha[:8]}"
        try:
            self.repo.git.checkout(commit_sha, b=branch_name)
            return branch_name
        except Exception:
            self.repo.git.checkout(branch_name)
            return branch_name

    def get_commit_history(self, limit: int = 50) -> List[Dict[str, Any]]:
        """Retrieve recent git commit log."""
        commits = []
        try:
            for commit in self.repo.iter_commits(max_count=limit):
                commits.append({
                    "sha": commit.hexsha,
                    "message": commit.message.strip(),
                    "author": str(commit.author),
                    "timestamp": commit.committed_datetime.isoformat(),
                })
        except Exception:
            pass
        return commits

"""Development version analyzer: status inference, regression detection, and heuristic recommendations."""

from typing import Optional, Tuple, List, Dict, Any
from devmemory.models import DevelopmentVersion, VersionStatus


LOWER_IS_BETTER_METRICS = {
    "latency", "latency_ms", "duration", "time", "loss", "train_loss",
    "val_loss", "error_rate", "cost", "memory_mb", "memory_used",
    "failures", "response_time", "p95_latency", "p99_latency"
}


def is_lower_better(metric_name: str) -> bool:
    """Determine whether a smaller value is better for a given metric name."""
    clean = metric_name.lower().replace("-", "_").strip()
    return any(term in clean for term in LOWER_IS_BETTER_METRICS)


def detect_regression(
    current_metrics: Dict[str, Any],
    current_tests_passed: Optional[int],
    current_tests_failed: Optional[int],
    previous_metrics: Dict[str, Any],
    previous_tests_passed: Optional[int],
    previous_tests_failed: Optional[int],
) -> Tuple[bool, List[str]]:
    """Detect if the current development step caused a regression relative to the previous version.

    Returns:
        (is_regression, reasons_list)
    """
    reasons: List[str] = []

    # 1. Test failure regression
    prev_failed = previous_tests_failed or 0
    curr_failed = current_tests_failed or 0
    if curr_failed > prev_failed:
        reasons.append(
            f"Test failures increased from {prev_failed} to {curr_failed} (+{curr_failed - prev_failed} failures)"
        )

    # 2. Test passed drop
    if previous_tests_passed is not None and current_tests_passed is not None:
        if current_tests_passed < previous_tests_passed:
            reasons.append(
                f"Passing tests dropped from {previous_tests_passed} to {current_tests_passed} (-{previous_tests_passed - current_tests_passed})"
            )

    # 3. Metric degradation (>5% tolerance)
    for k, v in current_metrics.items():
        if k in previous_metrics:
            try:
                curr_val = float(v)
                prev_val = float(previous_metrics[k])
            except (ValueError, TypeError):
                continue

            lower_better = is_lower_better(k)

            if lower_better:
                # E.g. latency jumped > 10%
                if prev_val > 0 and curr_val > prev_val * 1.10:
                    delta = curr_val - prev_val
                    pct = (delta / prev_val) * 100
                    reasons.append(
                        f"Metric '{k}' regressed: increased from {prev_val:.3f} to {curr_val:.3f} (+{pct:.1f}%)"
                    )
            else:
                # E.g. accuracy dropped > 5%
                if prev_val > 0 and curr_val < prev_val * 0.95:
                    delta = prev_val - curr_val
                    pct = (delta / prev_val) * 100
                    reasons.append(
                        f"Metric '{k}' regressed: decreased from {prev_val:.3f} to {curr_val:.3f} (-{pct:.1f}%)"
                    )

    is_reg = len(reasons) > 0
    return is_reg, reasons


def infer_status(
    tests_passed: Optional[int],
    tests_failed: Optional[int],
    errors: List[str],
    is_regression: bool,
    explicit_status: Optional[str] = None,
) -> VersionStatus:
    """Infer the development version status based on tests, errors, and regressions."""
    if explicit_status:
        try:
            return VersionStatus(explicit_status.upper())
        except ValueError:
            pass

    if errors and len(errors) > 0:
        return VersionStatus.ERROR

    if is_regression:
        return VersionStatus.REGRESSION

    if tests_failed is not None and tests_failed > 0:
        if tests_passed is not None and tests_passed > 0:
            return VersionStatus.PARTIAL_SUCCESS
        return VersionStatus.ERROR

    if tests_passed is not None and tests_passed > 0 and (tests_failed == 0 or tests_failed is None):
        return VersionStatus.SUCCESS

    return VersionStatus.SUCCESS


def generate_analysis_and_recommendation(
    version: DevelopmentVersion,
    previous: Optional[DevelopmentVersion] = None,
    regression_reasons: Optional[List[str]] = None,
) -> Tuple[str, str]:
    """Generate concise heuristic analysis and actionable recommendations for AI/human."""
    reasons = regression_reasons or []
    analysis_parts = []
    recommendation_parts = []

    # Analysis summary
    if version.is_regression:
        analysis_parts.append("REGRESSION DETECTED: " + "; ".join(reasons))
        recommendation_parts.append(
            "Do not deploy this change. Review git diff and investigate recent edits."
        )
        if version.feature:
            recommendation_parts.append(
                f"For feature '{version.feature}', revert or refine the implementation before proceeding."
            )
    elif version.status == VersionStatus.ERROR:
        analysis_parts.append("Execution or build errors encountered.")
        if version.errors:
            analysis_parts.append(f"Errors: {', '.join(version.errors[:2])}")
        recommendation_parts.append("Fix failing errors before committing further changes.")
    elif version.status == VersionStatus.SUCCESS:
        analysis_parts.append("All validations and tests passed successfully.")
        if previous and version.metrics and previous.metrics:
            improvements = []
            for k, v in version.metrics.items():
                if k in previous.metrics:
                    try:
                        cv, pv = float(v), float(previous.metrics[k])
                        if not is_lower_better(k) and cv > pv:
                            improvements.append(f"{k}: {pv:.2f} -> {cv:.2f}")
                        elif is_lower_better(k) and cv < pv:
                            improvements.append(f"{k}: {pv:.2f} -> {cv:.2f}")
                    except (ValueError, TypeError):
                        pass
            if improvements:
                analysis_parts.append("Metrics improved: " + ", ".join(improvements))
        recommendation_parts.append("State is stable. Proceed to next development milestone.")
    else:
        analysis_parts.append(f"Development step marked as {version.status.value}.")
        recommendation_parts.append("Continue implementation and run test suite.")

    analysis = " ".join(analysis_parts)
    recommendation = " ".join(recommendation_parts)
    return analysis, recommendation

"""Development memory module: searches previous attempts, finds past failures/regressions, and formats AI context."""

from typing import List, Dict, Any, Optional
import json
from devmemory.database import DevMemoryDB
from devmemory.models import VersionStatus


def _safe_json(val: Any) -> Any:
    if isinstance(val, (dict, list)):
        return val
    if not val:
        return {}
    try:
        return json.loads(val)
    except Exception:
        return {}


def find_similar_attempts(
    db: DevMemoryDB,
    intent: str = "",
    feature: str = "",
) -> List[Dict[str, Any]]:
    """Search previous development versions for failed or regressed attempts related to this feature or intent.

    Provides early warnings to developers and AI agents to prevent repeating known mistakes.
    """
    warnings: List[Dict[str, Any]] = []
    seen_ids = set()

    # 1. Search by feature
    if feature:
        feature_versions = db.get_versions_by_feature(feature)
        for v in feature_versions:
            status = v.get("status")
            is_reg = bool(v.get("is_regression"))
            if status in (VersionStatus.REGRESSION.value, VersionStatus.ERROR.value) or is_reg:
                vid = v.get("version_id")
                if vid not in seen_ids:
                    seen_ids.add(vid)
                    warnings.append({
                        "version_id": vid,
                        "feature": v.get("feature"),
                        "intent": v.get("intent"),
                        "agent": v.get("agent"),
                        "status": status,
                        "is_regression": is_reg,
                        "git_commit": v.get("git_commit", "")[:8],
                        "metrics": _safe_json(v.get("metrics")),
                        "analysis": v.get("analysis") or "Regression or error occurred.",
                        "recommendation": v.get("recommendation") or "Avoid repeating this approach.",
                        "timestamp": v.get("timestamp"),
                    })

    # 2. Search by intent query
    if intent and len(intent.strip()) > 2:
        try:
            matched = db.search_versions(intent.strip())
            for v in matched:
                status = v.get("status")
                is_reg = bool(v.get("is_regression"))
                if status in (VersionStatus.REGRESSION.value, VersionStatus.ERROR.value) or is_reg:
                    vid = v.get("version_id")
                    if vid not in seen_ids:
                        seen_ids.add(vid)
                        warnings.append({
                            "version_id": vid,
                            "feature": v.get("feature"),
                            "intent": v.get("intent"),
                            "agent": v.get("agent"),
                            "status": status,
                            "is_regression": is_reg,
                            "git_commit": v.get("git_commit", "")[:8],
                            "metrics": _safe_json(v.get("metrics")),
                            "analysis": v.get("analysis") or "Failed attempt detected.",
                            "recommendation": v.get("recommendation") or "Review diff before applying similar logic.",
                            "timestamp": v.get("timestamp"),
                        })
        except Exception:
            pass

    # Sort warnings with most recent first
    warnings.sort(key=lambda w: w.get("version_id", 0), reverse=True)
    return warnings


def format_agent_context(
    project_status: Dict[str, Any],
    warnings: List[Dict[str, Any]],
    features: Optional[List[Dict[str, Any]]] = None,
) -> str:
    """Format structured development context into a markdown prompt block for AI agents."""
    p_name = project_status.get("project_name", "Unknown Project")
    curr_v = project_status.get("current_version", 0)
    tot_v = project_status.get("total_versions", 0)
    latest_metrics = project_status.get("latest_metrics", {})

    lines = [
        f"### DevMemory Project Context: {p_name} (Current Version: v{curr_v})",
        f"- Total Development Iterations: {tot_v}",
    ]

    if latest_metrics:
        m_str = ", ".join([f"{k}: {v}" for k, v in latest_metrics.items()])
        lines.append(f"- Active Metrics Baseline: {m_str}")

    if features:
        done = [f["name"] for f in features if f.get("status") == "COMPLETE"]
        in_prog = [f["name"] for f in features if f.get("status") != "COMPLETE"]
        if done:
            lines.append(f"- Completed Features: {', '.join(done)}")
        if in_prog:
            lines.append(f"- Incomplete Features: {', '.join(in_prog)}")

    if warnings:
        lines.append("\n⚠️ **DEVELOPMENT MEMORY WARNINGS (Previous Regressions / Errors):**")
        for w in warnings[:5]:
            lines.append(
                f"- **v{w['version_id']} [{w['status']}]** (Feature: `{w.get('feature') or 'all'}`): "
                f"Intent: \"{w.get('intent') or 'N/A'}\". "
                f"Advice: {w.get('recommendation')}"
            )
    else:
        lines.append("\n✅ No relevant previous regressions recorded for this scope.")

    return "\n".join(lines)

"""DevMemory Model Context Protocol (MCP) Server.

Exposes project status, version history, previous attempt warnings, and diffs as MCP tools
for AI coding agents (Claude Code, Cursor, Antigravity, etc.).
Supports FastMCP if `mcp` is installed, with an integrated stdio JSON-RPC 2.0 server fallback.
"""

import sys
import json
import os
from typing import Dict, Any, List

from devmemory import DevMemoryProject


def get_project(project_path: str = ".") -> DevMemoryProject:
    return DevMemoryProject(project_path)


def run_mcp_server(project_path: str = "."):
    """Launch the MCP server for the given project path."""
    project_path = os.path.abspath(project_path)

    # Attempt FastMCP first
    try:
        from mcp.server.fastmcp import FastMCP

        mcp = FastMCP("DevMemory", dependencies=["devmemory"])
        proj = get_project(project_path)

        @mcp.tool()
        def get_project_status() -> Dict[str, Any]:
            """Get current project status, active version, test health, and baseline metrics."""
            return proj.status()

        @mcp.tool()
        def get_version_history(limit: int = 10) -> List[Dict[str, Any]]:
            """Get recent development version iterations with status, intent, and metrics."""
            return proj.history(limit=limit)

        @mcp.tool()
        def get_previous_attempts(feature: str = "", intent: str = "") -> Dict[str, Any]:
            """Check project memory for prior failed attempts or regressions before implementing changes."""
            return proj.context(feature=feature, intent=intent)

        @mcp.tool()
        def get_version_diff(version_a: int, version_b: int) -> Dict[str, Any]:
            """Compare two development versions (metrics delta, test changes, git diff)."""
            return proj.diff(version_a, version_b)

        @mcp.tool()
        def get_feature_status() -> List[Dict[str, Any]]:
            """Get status, metrics, and evolution history for all tracked features."""
            return proj.features()

        @mcp.tool()
        def get_project_context(feature: str = "", intent: str = "") -> str:
            """Get complete markdown prompt snippet formatted for AI agent decision-making."""
            ctx = proj.context(feature=feature, intent=intent)
            return ctx.get("prompt_snippet", "")

        mcp.run()
        return
    except ImportError:
        pass

    # Fallback to standard stdio JSON-RPC 2.0 MCP protocol
    _run_stdio_jsonrpc_mcp(project_path)


def _run_stdio_jsonrpc_mcp(project_path: str):
    """Integrated stdio JSON-RPC 2.0 server supporting core MCP tools."""
    proj = get_project(project_path)

    TOOLS = [
        {
            "name": "get_project_status",
            "description": "Get current project status, active version, test health, and baseline metrics.",
            "inputSchema": {"type": "object", "properties": {}},
        },
        {
            "name": "get_version_history",
            "description": "Get recent development version iterations with status, intent, and metrics.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "limit": {"type": "integer", "description": "Max versions to return", "default": 10}
                },
            },
        },
        {
            "name": "get_previous_attempts",
            "description": "Check development memory for past regressions or mistakes before modifying code.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "feature": {"type": "string", "description": "Feature name to inspect"},
                    "intent": {"type": "string", "description": "Proposed intent or description"},
                },
            },
        },
        {
            "name": "get_version_diff",
            "description": "Compare two development versions across code, tests, and metric changes.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "version_a": {"type": "integer", "description": "Base version ID"},
                    "version_b": {"type": "integer", "description": "Target version ID"},
                },
                "required": ["version_a", "version_b"],
            },
        },
        {
            "name": "get_feature_status",
            "description": "Get status, metrics, and evolution history for all tracked features.",
            "inputSchema": {"type": "object", "properties": {}},
        },
        {
            "name": "get_project_context",
            "description": "Get formatted markdown prompt snippet for AI coding agent decision making.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "feature": {"type": "string", "description": "Active feature name"},
                    "intent": {"type": "string", "description": "Proposed intent"},
                },
            },
        },
    ]

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except Exception:
            continue

        req_id = req.get("id")
        method = req.get("method")
        params = req.get("params", {})

        if method == "initialize":
            resp = {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "protocolVersion": "2024-11-05",
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "devmemory-mcp", "version": "0.1.0"},
                },
            }
        elif method == "tools/list":
            resp = {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {"tools": TOOLS},
            }
        elif method == "tools/call":
            tool_name = params.get("name")
            arguments = params.get("arguments", {})

            try:
                if tool_name == "get_project_status":
                    res = proj.status()
                elif tool_name == "get_version_history":
                    limit = int(arguments.get("limit", 10))
                    res = proj.history(limit=limit)
                elif tool_name == "get_previous_attempts":
                    res = proj.context(
                        feature=arguments.get("feature", ""),
                        intent=arguments.get("intent", ""),
                    )
                elif tool_name == "get_version_diff":
                    res = proj.diff(
                        version_a=int(arguments["version_a"]),
                        version_b=int(arguments["version_b"]),
                    )
                elif tool_name == "get_feature_status":
                    res = proj.features()
                elif tool_name == "get_project_context":
                    ctx = proj.context(
                        feature=arguments.get("feature", ""),
                        intent=arguments.get("intent", ""),
                    )
                    res = ctx.get("prompt_snippet", "")
                else:
                    res = {"error": f"Unknown tool '{tool_name}'"}

                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "content": [{"type": "text", "text": json.dumps(res, indent=2) if isinstance(res, (dict, list)) else str(res)}]
                    },
                }
            except Exception as e:
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {"code": -32000, "message": str(e)},
                }
        else:
            resp = {
                "jsonrpc": "2.0",
                "id": req_id,
                "error": {"code": -32601, "message": f"Method '{method}' not found"},
            }

        sys.stdout.write(json.dumps(resp) + "\n")
        sys.stdout.flush()


if __name__ == "__main__":
    run_mcp_server(os.getcwd())

"""Click CLI for DevMemory."""

import json
import os
import sys
import click

if sys.platform == "win32":
    try:
        if hasattr(sys.stdout, "reconfigure"):
            sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        if hasattr(sys.stderr, "reconfigure"):
            sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
