"""DevMemory configuration management."""

import json
import os
from dataclasses import dataclass, field
from typing import Optional


DEVMEMORY_DIR = ".devmemory"
CONFIG_FILE = "config.json"


@dataclass
class DevMemoryConfig:
    """Project-level DevMemory configuration."""

    project_id: str = ""
    project_name: str = ""
    project_path: str = ""
    databricks_host: Optional[str] = None
    databricks_http_path: Optional[str] = None
    databricks_token: Optional[str] = None
    databricks_catalog: str = "devmemory_analytics"
    databricks_schema: str = "development_intelligence"
    web_host: str = "127.0.0.1"
    web_port: int = 8765

    @classmethod
    def load(cls, project_path: str) -> "DevMemoryConfig":
        """Load config from .devmemory/config.json."""
        config_path = os.path.join(project_path, DEVMEMORY_DIR, CONFIG_FILE)
        if not os.path.exists(config_path):
            # Return defaults with inferred project name
            return cls(
                project_path=project_path,
                project_name=os.path.basename(project_path),
                project_id=os.path.basename(project_path).lower().replace(" ", "-"),
            )
        with open(config_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return cls(**data)

    @classmethod
    def create(
        cls, project_path: str, name: str = "", project_id: str = ""
    ) -> "DevMemoryConfig":
        """Create a new config and save to disk."""
        dm_dir = os.path.join(project_path, DEVMEMORY_DIR)
        os.makedirs(dm_dir, exist_ok=True)
        os.makedirs(os.path.join(dm_dir, "artifacts"), exist_ok=True)

        # Add .devmemory to .gitignore if it exists
        gitignore_path = os.path.join(project_path, ".gitignore")
        _ensure_gitignore(gitignore_path)

        config = cls(
            project_path=project_path,
            project_name=name or os.path.basename(project_path),
            project_id=project_id
            or os.path.basename(project_path).lower().replace(" ", "-"),
        )
        config.save()
        return config

    def save(self):
        """Save config to disk."""
        config_path = os.path.join(self.project_path, DEVMEMORY_DIR, CONFIG_FILE)
        os.makedirs(os.path.dirname(config_path), exist_ok=True)
        data = {
            "project_id": self.project_id,
            "project_name": self.project_name,
            "project_path": self.project_path,
            "databricks_host": self.databricks_host,
            "databricks_http_path": self.databricks_http_path,
            "databricks_token": self.databricks_token,
            "databricks_catalog": self.databricks_catalog,
            "databricks_schema": self.databricks_schema,
            "web_host": self.web_host,
            "web_port": self.web_port,
        }
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

    @property
    def db_path(self) -> str:
        return os.path.join(self.project_path, DEVMEMORY_DIR, "devmemory.db")

    @property
    def artifacts_dir(self) -> str:
        return os.path.join(self.project_path, DEVMEMORY_DIR, "artifacts")

    @property
    def devmemory_dir(self) -> str:
        return os.path.join(self.project_path, DEVMEMORY_DIR)


def _ensure_gitignore(gitignore_path: str):
    """Add .devmemory/ to .gitignore if not already present."""
    entry = ".devmemory/"
    if os.path.exists(gitignore_path):
        with open(gitignore_path, "r", encoding="utf-8") as f:
            content = f.read()
        if entry not in content:
            with open(gitignore_path, "a", encoding="utf-8") as f:
                f.write(f"\n# DevMemory local data\n{entry}\n")
    else:
        with open(gitignore_path, "w", encoding="utf-8") as f:
            f.write(f"# DevMemory local data\n{entry}\n")

"""REST API router for DevMemory web dashboard."""

from fastapi import APIRouter, HTTPException, Query
from typing import Optional
from devmemory import DevMemoryProject


def _get_proj(project_path: str = ".") -> DevMemoryProject:
    return DevMemoryProject(project_path)


def create_api_router(project_path: str = ".") -> APIRouter:
    api = APIRouter(prefix="/api")

    @api.get("/project")
    def get_project_summary():
        proj = _get_proj(project_path)
        return proj.status()

    @api.get("/versions")
    def get_versions(limit: int = Query(100, ge=1, le=500)):
        proj = _get_proj(project_path)
        return proj.history(limit=limit)

    # CRITICAL: /versions/compare MUST come BEFORE /versions/{version_id}
    # so FastAPI does not match 'compare' as an integer version_id!
    @api.get("/versions/compare")
    @api.get("/compare")
    def compare_versions(a: str = Query(...), b: str = Query(...)):
        proj = _get_proj(project_path)
        try:
            val_a = int(str(a).lower().lstrip("v"))
            val_b = int(str(b).lower().lstrip("v"))
        except ValueError:
            raise HTTPException(status_code=400, detail="Invalid version IDs provided. Expected integers, e.g. 2, 3 or v2, v3")

        res = proj.diff(val_a, val_b)
        if "error" in res:
            raise HTTPException(status_code=400, detail=res["error"])
        return res

    @api.get("/versions/{version_id}")
    def get_version_detail(version_id: int):
        proj = _get_proj(project_path)
        v = proj.db.get_version(version_id)
        if not v:
            raise HTTPException(status_code=404, detail="Version not found")
        hist = proj.history(limit=500)
        found = next((item for item in hist if item["version_id"] == version_id), dict(v))
        return found

    @api.get("/features")
    def get_features():
        proj = _get_proj(project_path)
        return proj.features()

    @api.get("/search")
    def search(q: str = Query(..., min_length=1)):
        proj = _get_proj(project_path)
        return proj.search(q)

    @api.get("/warnings")
    def get_warnings(feature: Optional[str] = "", intent: Optional[str] = ""):
        proj = _get_proj(project_path)
        return proj.context(feature=feature or "", intent=intent or "")

    @api.post("/versions/{version_id}/restore")
    def restore_version(version_id: int):
        proj = _get_proj(project_path)
        res = proj.restore(version_id)
        if "error" in res:
            raise HTTPException(status_code=400, detail=res["error"])
        return res

    @api.get("/analytics")
    def get_analytics():
        proj = _get_proj(project_path)
        return proj.analytics()

    return api

