def _parse_numstat(self, raw: str) -> list[ChangedFile]:
    files: list[ChangedFile] = []
    tokens = [t for t in raw.split(_NUL) if t != ""]
    i = 0
    while i < len(tokens):
        line = tokens[i]
        bits = line.split("\t")
        if len(bits) < 3:
            i += 1
            continue
        add_s, del_s, path = bits[0], bits[1], bits[2]
        binary = add_s == "-" or del_s == "-"
        # Rename entries in -z numstat put "" then old then new in following tokens.
        if path == "" and i + 2 < len(tokens):
            path = tokens[i + 2]
            i += 3
        else:
            i += 1
        files.append(
            ChangedFile(
                path=path,
                change_type=ChangeType.MODIFIED,
                additions=0 if binary else int(add_s),
                deletions=0 if binary else int(del_s),
                binary=binary,
            )
        )
    return files

