class _ProbeCache:
    """The Entire probe shells out; cache it briefly so the dashboard stays snappy."""

    def __init__(self) -> None:
        self._at = 0.0
        self._value: EntireStatus | None = None

    def get(self, ctx: ProjectContext) -> EntireStatus:
        now = time.monotonic()
